package com.almajedi.vip;
import android.app.*;import android.content.*;import android.os.Build;import android.content.pm.PackageManager;import com.google.android.gms.location.*;
public class FenceReceiver extends BroadcastReceiver {public void onReceive(Context c,Intent i){GeofencingEvent e=GeofencingEvent.fromIntent(i);if(e==null||e.hasError()||e.getGeofenceTransition()!=Geofence.GEOFENCE_TRANSITION_ENTER)return;var p=c.getSharedPreferences("vip",0);if(!p.getBoolean("enabled",false))return;long now=System.currentTimeMillis();if(now-p.getLong("last",0)<86400000L)return;if(Build.VERSION.SDK_INT>=33&&c.checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)return; NotificationManager n=c.getSystemService(NotificationManager.class);n.createNotificationChannel(new NotificationChannel("near","عروض المجيدي بالقرب منك",NotificationManager.IMPORTANCE_DEFAULT));if(!n.areNotificationsEnabled())return;n.notify(1,new Notification.Builder(c,"near").setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle("يا هلا بك بالقرب من المجيدي 🧡").setContentText("مرّ علينا، نقاطك وهداياك بانتظارك!").setAutoCancel(true).setContentIntent(PendingIntent.getActivity(c,2,new Intent(c,MainActivity.class),PendingIntent.FLAG_IMMUTABLE)).build());p.edit().putLong("last",now).apply();}}
